"""Dependency-free administration UI assets served only by the Ingress listener."""

ADMIN_CSS = """
:root{color-scheme:light;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--navy:#142f4b;--cyan:#058caf;--cyan-soft:#dff5fa;--amber:#e9a72f;--amber-soft:#fff5df;--good:#16845b;--bad:#c43f55;--shadow:0 5px 22px #1e3a5f12}
html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--navy:#101b2a;--cyan:#52c9e6;--cyan-soft:#173b4a;--amber:#f0b84e;--amber-soft:#493b20;--good:#50c895;--bad:#ff8293;--shadow:none}
*{box-sizing:border-box}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}.app{max-width:1440px;margin:auto;padding:24px}.top{display:flex;align-items:center;gap:20px;margin-bottom:26px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;margin-right:auto;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase}.nav{display:flex;align-items:center;gap:5px}.nav a,.theme{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px;border:0;background:transparent;font:inherit}.nav .active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.theme{background:var(--surface);border:1px solid var(--line);cursor:pointer;font-size:17px}.view{display:none}.view.active{display:block}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center;margin:4px 0 20px}.hero h1,.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.hero p,.pagehead p{margin:0;color:var(--muted)}.pagehead{margin:4px 0 20px}.pagehead.split{display:flex;align-items:center;justify-content:space-between;gap:18px}.export{color:#fff;background:var(--cyan);text-decoration:none;padding:10px 14px;border-radius:7px;font-weight:700;white-space:nowrap}.health{display:flex;align-items:center;gap:8px;color:var(--good);font-weight:700;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:11px 14px;box-shadow:var(--shadow)}.health i{width:9px;height:9px;border-radius:50%;background:currentColor;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 15%,transparent)}.health a{color:inherit;text-decoration:none}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px;margin:0 0 16px}.metric{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow);position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric.amber:before{background:var(--amber)}.metric strong{display:block;font-size:29px;font-variant-numeric:tabular-nums;line-height:1.1}.metric span{display:block;color:var(--muted);margin-top:5px}.workspace{display:grid;grid-template-columns:minmax(310px,390px) minmax(0,1fr);gap:12px}.card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:var(--shadow)}.cardhead{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:18px}.card h2{margin:0 0 4px;font-size:19px}.cardhead p{margin:0;color:var(--muted);font-size:13px}.count{background:var(--surface2);color:var(--muted);border-radius:999px;padding:4px 9px;font-size:12px}label{display:block;font-weight:650;margin:13px 0 5px}input,select{display:block;width:100%;padding:10px 11px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px;outline:none}input:focus,select:focus{border-color:var(--cyan);box-shadow:0 0 0 3px var(--cyan-soft)}fieldset{border:0;padding:0;margin:16px 0}legend{font-weight:700;margin-bottom:8px}.permission{display:flex;align-items:flex-start;gap:9px;padding:8px 9px;margin:0;border-radius:7px;font-weight:400;cursor:pointer}.permission:hover{background:var(--surface2)}.permission input{width:auto;margin:3px 0}.permission span{display:block}.permission small{display:block;color:var(--muted);margin-top:2px}button.primary,.danger{border:0;border-radius:7px;padding:10px 14px;font-weight:700;cursor:pointer}.primary{background:var(--cyan);color:#fff;width:100%}.danger{background:transparent;color:var(--bad);border:1px solid color-mix(in srgb,var(--bad) 45%,var(--line));padding:7px 10px}.danger:hover{background:color-mix(in srgb,var(--bad) 9%,transparent)}.identities{min-height:300px}.identity{border-top:1px solid var(--line);padding:16px 0}.identity:first-child{border-top:0;padding-top:0}.identity:last-child{padding-bottom:0}.identityhead{display:flex;justify-content:space-between;gap:12px}.identityname{font-weight:750}.identitymeta{color:var(--muted);font-size:13px;margin-top:3px}.pill{display:inline-block;padding:3px 8px;border-radius:999px;background:var(--cyan-soft);color:var(--cyan);font-size:12px}.pill.revoked{background:color-mix(in srgb,var(--bad) 12%,var(--surface));color:var(--bad)}.actions{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--muted);overflow-wrap:anywhere}.empty{text-align:center;padding:45px 18px;color:var(--muted)}.emptyicon{display:grid;place-items:center;width:52px;height:52px;margin:0 auto 12px;border-radius:14px;background:var(--surface2);color:var(--cyan);font-size:23px}.credential{display:none;margin-top:16px;padding:15px;background:var(--amber-soft);border:1px solid color-mix(in srgb,var(--amber) 55%,var(--line));border-radius:9px}.credential.show{display:block}.credential code{display:block;overflow-wrap:anywhere;margin:10px 0;padding:10px;background:var(--surface);border-radius:6px}.credential strong{color:var(--text)}.error{color:var(--bad)}.loading{color:var(--muted)}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted);background:var(--surface2)}tr:last-child td{border:0}td.wrap{white-space:normal;min-width:220px}details summary{color:var(--cyan);cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface2);padding:12px;border-radius:7px;font-size:12px;max-width:650px}.state{display:inline-block;padding:3px 8px;border-radius:999px;background:var(--amber-soft);color:var(--amber);font-size:12px}.state.completed,.state.allowed{background:var(--cyan-soft);color:var(--good)}.state.denied{background:color-mix(in srgb,var(--bad) 12%,var(--surface));color:var(--bad)}
@media(max-width:850px){.app{padding:16px}.top{align-items:flex-start;flex-wrap:wrap}.brand{width:100%}.nav{max-width:100%;overflow-x:auto}.hero{grid-template-columns:1fr}.health{justify-self:start}.workspace{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(3,1fr)}}
@media(max-width:560px){.metrics{grid-template-columns:1fr}.hero h1{font-size:25px}.nav .future{display:none}}
"""

ADMIN_JS = r"""
const root=document.querySelector('main'),base=root.dataset.base,csrf=root.dataset.csrf;
const themeButton=document.querySelector('#theme');
const setTheme=value=>{document.documentElement.dataset.theme=value;localStorage.setItem('agw-theme',value);themeButton.textContent=value==='dark'?'☀':'☾';themeButton.title=value==='dark'?'Mode clair':'Mode sombre'};
setTheme(localStorage.getItem('agw-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
themeButton.onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
const api=(path,options={})=>fetch(base+path,{...options,headers:{'X-CSRF-Token':csrf,'Content-Type':'application/json',...(options.headers||{})}}).then(async r=>{const body=await r.json();if(!r.ok)throw new Error(body.error?.code||`HTTP ${r.status}`);return body});
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const date=value=>value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Jamais';
const empty=(icon,title,text)=>`<div class="empty"><div class="emptyicon">${icon}</div><strong>${title}</strong><p>${text}</p></div>`;
const table=(headers,rows)=>rows.length?`<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`:'';
async function loadPanel(id,path,key,headers,renderRows,emptyState){const panel=document.querySelector(id);try{const data=await api(path);panel.innerHTML=table(headers,renderRows(data[key]))||empty(...emptyState)}catch(error){panel.innerHTML=empty('!','Chargement impossible',`La vue est temporairement indisponible (${esc(error.message)}).`)}}
async function loadOperationalViews(){await Promise.all([
loadPanel('#events-list','/admin/api/v1/events','events',['Reçu','Type','Source','Sujet','Détail'],items=>items.map(e=>`<tr><td>${esc(date(e.received_at))}</td><td><span class="pill">${esc(e.event_type)}</span></td><td>${esc(e.source_name)}</td><td>${esc(e.payload?.subject?.entity_id||'—')}</td><td><details><summary>Afficher</summary><pre>${esc(JSON.stringify(e.payload,null,2))}</pre></details></td></tr>`),['↯','Aucun événement','Les événements authentifiés apparaîtront ici.']),
loadPanel('#jobs-list','/admin/api/v1/jobs','jobs',['Créée','Tâche','État','Événement','Rapports','Action'],items=>items.map(j=>`<tr><td>${esc(date(j.created_at))}</td><td>${esc(j.task_name)}</td><td><span class="state ${j.state}">${esc(j.state)}</span></td><td>${esc(j.event_id||'—')}</td><td>${esc(j.report_count)}</td><td>${j.state==='queued'?`<button class="danger cancel-job" data-id="${esc(j.id)}">Annuler</button>`:'—'}</td></tr>`),['◇','Aucune tâche','Les demandes acceptées seront placées dans cette file persistante.']),
loadPanel('#reports-list','/admin/api/v1/reports','reports',['Créé','Tâche','Tâche ID','Détail'],items=>items.map(r=>`<tr><td>${esc(date(r.created_at))}</td><td>${esc(r.task_name)}</td><td>${esc(r.job_id)}</td><td><details><summary>Afficher</summary><pre>${esc(JSON.stringify(r.report,null,2))}</pre></details></td></tr>`),['▤','Aucun rapport','Les résultats structurés produits par les agents apparaîtront ici.']),
loadPanel('#audit-list','/admin/api/v1/audit','audit_entries',['Date','Décision','Action','Acteur','Motif','Contexte'],items=>items.map(a=>`<tr><td>${esc(date(a.occurred_at))}</td><td><span class="state ${esc(a.decision)}">${esc(a.decision)}</span></td><td>${esc(a.action)}</td><td>${esc(a.actor_name||'Système / inconnu')}</td><td>${esc(a.reason_code)}</td><td><details><summary>Afficher</summary><pre>${esc(JSON.stringify({correlation_id:a.correlation_id,target_type:a.target_type,target_id:a.target_id,metadata:a.metadata},null,2))}</pre></details></td></tr>`),['⌁','Journal vide','Les décisions de sécurité apparaîtront ici.'])]);document.querySelectorAll('.cancel-job').forEach(button=>button.onclick=async()=>{if(confirm('Annuler définitivement cette tâche en attente ?')){try{await api('/admin/api/v1/jobs/cancel',{method:'POST',body:JSON.stringify({job_id:button.dataset.id})});await loadOperationalViews()}catch(error){alert(`Annulation impossible : ${error.message}`)}}})}
function showView(name){const target=['overview','events','jobs','reports','audit'].includes(name)?name:'overview';document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===target));document.querySelectorAll('.nav [data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===target));if(location.hash!==`#${target}`)history.replaceState(null,'',`#${target}`)}
document.querySelectorAll('.nav [data-view]').forEach(a=>a.onclick=event=>{event.preventDefault();showView(a.dataset.view)});window.addEventListener('hashchange',()=>showView(location.hash.slice(1)));
async function refresh(){const [status,data]=await Promise.all([api('/admin/api/v1/status'),api('/admin/api/v1/identities')]);document.querySelector('#total').textContent=status.identities;document.querySelector('#active').textContent=status.active_identities;document.querySelector('#revoked').textContent=status.identities-status.active_identities;document.querySelector('#identity-count').textContent=status.identities;document.querySelector('#identities').innerHTML=data.identities.length?data.identities.map(i=>`<article class="identity"><div class="identityhead"><div><div class="identityname">${esc(i.display_name)}</div><div class="identitymeta">${esc(i.identity_type)} · créée ${esc(date(i.created_at))} · dernière utilisation ${esc(date(i.last_used_at))}</div></div><span class="pill ${i.status==='revoked'?'revoked':''}">${i.status==='active'?'Active':'Révoquée'}</span></div><p class="actions">${esc(i.gateway_actions.join(' · ')||'Aucune permission')}</p>${i.status==='active'?`<button class="danger revoke" data-id="${esc(i.id)}">Révoquer</button>`:''}</article>`).join(''):'<div class="empty"><div class="emptyicon">◇</div><strong>Aucune identité</strong><p>Créez votre premier client MCP ou une source d’événements.</p></div>';document.querySelectorAll('.revoke').forEach(b=>b.onclick=async()=>{if(confirm('Révoquer immédiatement cette identité et tous ses identifiants ?')){await api('/admin/api/v1/identities/revoke',{method:'POST',body:JSON.stringify({identity_id:b.dataset.id})});refresh()}})}
document.querySelector('#create').onsubmit=async event=>{event.preventDefault();const message=document.querySelector('#message');message.textContent='';const form=new FormData(event.target),actions=form.getAll('actions');if(actions.includes('jobs.claim'))actions.push(...form.get('worker_actions').split(','));try{const result=await api('/admin/api/v1/identities',{method:'POST',body:JSON.stringify({display_name:form.get('display_name'),identity_type:form.get('identity_type'),actions})});const box=document.querySelector('#credential');box.classList.add('show');box.querySelector('code').textContent=result.credential;event.target.reset();await refresh()}catch(error){message.textContent=error.message}};
showView(location.hash.slice(1));
Promise.all([refresh(),loadOperationalViews()]).catch(error=>document.querySelector('#message').textContent=error.message);
"""
